process.env.MODO_TESTE = '1';
const request = require('supertest');
const { criarServidor } = require('../src/app');

describe('M2-RN-221/222 — Listagem', () => {
  let app;
  beforeEach(() => { app = criarServidor(); });

  it('ordena por criadaEm e participante vê só as próprias', async () => {
    await request(app).post('/_teste/reset').expect(204);
    const mk = async (titulo, sala, h1, h2) => {
      const r = await request(app).post('/atividades').set('X-Usuario', 'org-ana').send({
        titulo, tipo: 'minicurso', salaId: sala, vagas: 20,
        encontros: [
          { inicio: `2026-10-19T${h1}-03:00`, fim: `2026-10-19T${h2}-03:00` },
          { inicio: `2026-10-20T${h1}-03:00`, fim: `2026-10-20T${h2}-03:00` },
        ]
      });
      return r.body.id;
    };
    const a1 = await mk('A1', 'sala-101', '08:00:00', '10:00:00');
    const a2 = await mk('A2', 'sala-102', '11:00:00', '13:00:00');
    const i1 = await request(app).post(`/atividades/${a1}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
    await request(app).put('/_teste/relogio').send({ agora: '2026-10-13T10:00:00-03:00' });
    const i2 = await request(app).post(`/atividades/${a2}/inscricoes`).set('X-Usuario', 'p-carla').expect(201);
    await request(app).post(`/atividades/${a1}/inscricoes`).set('X-Usuario', 'p-joao').expect(201);

    const lista = await request(app).get('/inscricoes').set('X-Usuario', 'p-carla').expect(200);
    expect(lista.body.map((i) => i.id)).toEqual([i1.body.id, i2.body.id]);
    expect(new Date(lista.body[0].criadaEm).getTime()).toBeLessThanOrEqual(new Date(lista.body[1].criadaEm).getTime());
  });

  it('filtro atividadeId inexistente retorna [] com 200', async () => {
    await request(app).post('/_teste/reset').expect(204);
    const resp = await request(app).get('/inscricoes?atividadeId=atv_inexistente').set('X-Usuario', 'p-carla');
    expect(resp.status).toBe(200);
    expect(resp.body).toEqual([]);
  });
});
